<script lang="ts">
  import { membershipCatalog as catalog, membershipCopy } from '#lib/memberships.ts';
  import type { Lang } from '#lib/site.ts';
  import Icon from './Icon.svelte';
  let { lang }: { lang: Lang } = $props();
  const c = $derived(membershipCopy[lang]);
  let participants = $state(catalog.privateLessons[0].participants), lessons = $state(8);
  const group = $derived(catalog.privateLessons.find(group => group.participants === participants) ?? catalog.privateLessons[0]);
  const chosen = $derived(group.packages.find(pack => pack.lessons === lessons) ?? group.packages[0]);
  const currency = $derived(new Intl.NumberFormat(lang === 'tr' ? 'tr-TR' : 'en-GB', { style: 'currency', currency: catalog.currency, currencyDisplay: 'narrowSymbol' }).formatToParts(0).find(part => part.type === 'currency')?.value || catalog.currency);
  const money = (amount: number, decimals = 0) => new Intl.NumberFormat(lang === 'tr' ? 'tr-TR' : 'en-GB', { maximumFractionDigits: decimals }).format(amount);
  const duration = (months: number) => lang === 'en' && months === 1 ? '1 month' : `${months} ${c.month}`;
</script>

<div id="private-lessons" class="private-lessons">
  <div class="private-people" role="group" aria-label={c.people}>{#each catalog.privateLessons as option}<button class:active={participants === option.participants} aria-pressed={participants === option.participants} onclick={() => { participants = option.participants; lessons = 8; }}><span>0{option.participants}</span><strong>{option.participants} {lang === 'en' && option.participants === 1 ? 'person' : c.person}</strong></button>{/each}</div>
  <div class="private-layout"><div class="private-intro"><span class="eyebrow">SELF CONTROL / PERSONAL TRAINING</span><h4>{participants === 1 ? c.individual : c.together}</h4><p>{c.intro}</p><div class="private-facts"><span><Icon name="clock" size={17}/>{group.sessionMinutes} {c.minute}</span><span><Icon name="training" size={17}/>{participants} {lang === 'en' && participants === 1 ? 'person' : c.person}</span></div><p class="private-price-note">{c.priceNote}</p></div>
  <div class="private-offers"><div class="private-package-list" role="group" aria-label={c.packages}>{#each group.packages as pack}<button class="private-package" class:chosen={chosen.lessons === pack.lessons} aria-pressed={chosen.lessons === pack.lessons} onclick={() => lessons = pack.lessons}><span class="package-radio" aria-hidden="true"></span><span class="private-package-name"><strong>{pack.lessons} {c.lessons}</strong><small>{pack.validityMonths ? `${c.validity}: ${duration(pack.validityMonths)}` : c.single}</small></span><span class="private-package-price"><strong>{currency}{money(pack.price)}</strong><small>{c.perPerson}</small></span></button>{/each}</div>
  <div class="private-summary" aria-live="polite"><span class="eyebrow">{c.selected} / {chosen.lessons} {c.lessons}</span><div class="private-summary-total"><span>{c.total}</span><strong>{currency}{money(chosen.price)}</strong></div><p>{currency}{money(chosen.price / chosen.lessons, 2)} {c.lesson} · {group.sessionMinutes} {c.minute}</p><a class="button solid" href="#start">{c.ask}<Icon name="diagonal" size={19}/></a></div></div></div>
  <p class="pricing-note">{c.note}</p>
</div>

